import React from 'react';
import './NoticeBar.css';

const NoticeBar = () => {
  return (
    <div className="notice-bar-container">
      <div className="notice-wrapper">
        <span className="notice-badge">LATEST NOTICE</span>
        
        {/* The marquee tag makes the text scroll like a news flyer */}
        <marquee className="notice-message" behavior="scroll" direction="left" scrollamount="6">
          Infinity Laghubitta Bittiya Sanstha Limited: Annual General Meeting (AGM) notice has been published. 
          Please visit our Investor Relations page for more details. &nbsp;&nbsp;&nbsp;&nbsp; 
          Our new interest rates are effective from today!
        </marquee>
      </div>
    </div>
  );
};

export default NoticeBar;
